import { useCallback, useEffect, useState } from 'react';
import confetti from 'canvas-confetti';
import { Check, RotateCcw } from 'lucide-react';
import './index.css';
import { byId, type Category } from './data/products';
import { SAMPLE_ORDERS, clearStorage, usePersistent, type CartLine, type Order } from './lib/store';
import Header, { Logo } from './components/Header';
import Catalog from './components/Catalog';
import ProductPage from './components/ProductPage';
import CartDrawer from './components/CartDrawer';
import Checkout from './components/Checkout';
import Wishlist from './components/Wishlist';
import Orders, { Confirmation } from './components/Orders';

type View =
  | { name: 'tienda' } | { name: 'producto'; id: string } | { name: 'deseos' }
  | { name: 'pedidos' } | { name: 'checkout' } | { name: 'confirmacion'; orderId: string };

export default function App() {
  const [view, setView] = useState<View>({ name: 'tienda' });
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState<Category | 'Todo'>('Todo');
  const [cart, setCart] = usePersistent<CartLine[]>('carrito', [
    { key: 'camiseta||M', productId: 'camiseta', size: 'M', qty: 1 },
  ]);
  const [code, setCode] = usePersistent<string | undefined>('codigo', undefined);
  const [wishlist, setWishlist] = usePersistent<string[]>('deseos', ['pulso-s2', 'jersey']);
  const [orders, setOrders] = usePersistent<Order[]>('pedidos', SAMPLE_ORDERS);
  const [cartOpen, setCartOpen] = useState(false);
  const [toast, setToast] = useState<string | null>(null);
  const [confirmReset, setConfirmReset] = useState(false);

  useEffect(() => { window.scrollTo({ top: 0 }); }, [view]);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 2600);
    return () => clearTimeout(t);
  }, [toast]);

  const go = (v: View) => { setView(v); setCartOpen(false); };
  const openProduct = (id: string) => go({ name: 'producto', id });
  const home = () => { setCategory('Todo'); go({ name: 'tienda' }); };

  const searchFor = (q: string) => { setQuery(q); if (view.name !== 'tienda') setView({ name: 'tienda' }); };
  const pickCategory = (c: Category | 'Todo') => { setCategory(c); setQuery(''); go({ name: 'tienda' }); };

  const toggleWish = (id: string) => {
    const has = wishlist.includes(id);
    setWishlist(w => (has ? w.filter(x => x !== id) : [...w, id]));
    setToast(has ? 'Quitado de tu lista de deseos' : 'Guardado en tu lista de deseos');
  };

  const addToCart = (productId: string, qty: number, color?: string, size?: string) => {
    const p = byId(productId);
    if (!p) return;
    const key = `${productId}|${color ?? ''}|${size ?? ''}`;
    const cap = Math.min(10, p.stock);
    setCart(c => {
      const found = c.find(l => l.key === key);
      if (found) return c.map(l => (l.key === key ? { ...l, qty: Math.min(cap, l.qty + qty) } : l));
      return [...c, { key, productId, color, size, qty: Math.min(cap, qty) }];
    });
    setCartOpen(true);
  };
  const quickAdd = (id: string) => addToCart(id, 1, byId(id)?.colors?.[0].name);
  const setQty = (key: string, qty: number) => setCart(c => c.map(l => (l.key === key ? { ...l, qty: Math.max(1, qty) } : l)));
  const remove = (key: string) => { setCart(c => c.filter(l => l.key !== key)); setToast('Producto eliminado del carrito'); };
  const closeCart = useCallback(() => setCartOpen(false), []);

  const place = (o: Omit<Order, 'id' | 'createdAt' | 'status'>) => {
    const order: Order = { ...o, id: `OB-${Math.floor(48000 + Math.random() * 9000)}`, createdAt: new Date().toISOString(), status: 'Confirmado' };
    setOrders(list => [order, ...list]);
    setCart([]);
    setCode(undefined);
    go({ name: 'confirmacion', orderId: order.id });
    confetti({ particleCount: 90, spread: 70, origin: { y: 0.3 }, colors: ['#2E4BF0', '#F2C230', '#17181C', '#B8CDBD'] });
  };

  const reset = () => {
    clearStorage();
    setCart([{ key: 'camiseta||M', productId: 'camiseta', size: 'M', qty: 1 }]);
    setCode(undefined); setWishlist(['pulso-s2', 'jersey']); setOrders(SAMPLE_ORDERS);
    setConfirmReset(false); home(); setToast('Datos de la demo restablecidos');
  };

  const cartCount = cart.reduce((s, l) => s + l.qty, 0);
  const active = view.name === 'tienda' ? 'tienda' : view.name === 'deseos' ? 'deseos' : view.name === 'pedidos' ? 'pedidos' : 'otro';
  const confirmed = view.name === 'confirmacion' ? orders.find(o => o.id === view.orderId) : undefined;

  return (
    <div className="objeto flex min-h-screen flex-col bg-[#F4F4F1] text-[#17181C]">
      <Header query={query} setQuery={searchFor} category={category} onCategory={pickCategory} onHome={home}
        onWishlist={() => go({ name: 'deseos' })} onOrders={() => go({ name: 'pedidos' })} onCart={() => setCartOpen(true)}
        wishCount={wishlist.length} cartCount={cartCount} active={active} />

      <main className="flex-1">
        {view.name === 'tienda' && (
          <Catalog query={query} setQuery={setQuery} category={category} setCategory={setCategory}
            wishlist={wishlist} toggleWish={toggleWish} openProduct={openProduct} />
        )}
        {view.name === 'producto' && (
          <ProductPage key={view.id} id={view.id} wishlist={wishlist} toggleWish={toggleWish} openProduct={openProduct} back={home} addToCart={addToCart} />
        )}
        {view.name === 'deseos' && <Wishlist ids={wishlist} toggleWish={toggleWish} openProduct={openProduct} back={home} quickAdd={quickAdd} />}
        {view.name === 'pedidos' && <Orders orders={orders} back={home} />}
        {view.name === 'checkout' && <Checkout lines={cart} code={code} back={home} place={place} />}
        {view.name === 'confirmacion' && confirmed && <Confirmation order={confirmed} back={home} toOrders={() => go({ name: 'pedidos' })} />}
      </main>

      <footer className="border-t border-[#E4E5E0] bg-[#ECEDE8]">
        <div className="mx-auto flex max-w-[1240px] flex-col gap-6 px-4 py-10 md:flex-row md:items-start md:justify-between md:px-8">
          <div className="max-w-xs">
            <Logo onClick={home} />
            <p className="mt-3 text-sm text-[#5B6068]">Tecnología y ropa elegidas para durar. Tienda en Fuencarral 43, Madrid · Atención de lunes a sábado, 10:00–20:00.</p>
          </div>
          <dl className="grid grid-cols-2 gap-x-10 gap-y-2 text-sm">
            <dt className="text-[#5B6068]">Envío estándar</dt><dd className="text-[#17181C]">4,90 € · gratis desde 60 €</dd>
            <dt className="text-[#5B6068]">Exprés 24 h</dt><dd className="text-[#17181C]">9,90 €</dd>
            <dt className="text-[#5B6068]">Devoluciones</dt><dd className="text-[#17181C]">30 días, gratis</dd>
          </dl>
          <div className="text-sm">
            {confirmReset ? (
              <div className="flex items-center gap-2">
                <span className="text-[#3A3D43]">¿Borrar carrito, deseos y pedidos?</span>
                <button onClick={reset} className="rounded-full bg-[#C2252B] px-3 py-1.5 font-semibold text-white">Sí, restablecer</button>
                <button onClick={() => setConfirmReset(false)} className="px-2 py-1.5 text-[#3A3D43] hover:underline">Cancelar</button>
              </div>
            ) : (
              <button onClick={() => setConfirmReset(true)} className="flex items-center gap-1.5 text-[#3A3D43] hover:text-[#17181C] hover:underline"><RotateCcw size={14} />Restablecer datos de la demo</button>
            )}
          </div>
        </div>
      </footer>

      {cartOpen && (
        <CartDrawer lines={cart} code={code} setCode={setCode} setQty={setQty} remove={remove} close={closeCart}
          checkout={() => go({ name: 'checkout' })} openProduct={openProduct} />
      )}
      {toast && (
        <div className="pointer-events-none fixed inset-x-0 bottom-5 z-[60] flex justify-center px-4" role="status">
          <div className="toast-enter flex items-center gap-2 rounded-full bg-[#17181C] px-5 py-3 text-sm font-medium text-white shadow-xl">
            <Check size={16} className="text-[#F2C230]" />{toast}
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Minus, Plus, ShoppingBag, Tag, Trash2, X } from 'lucide-react';
import { byId } from '../data/products';
import { eur, eurExact } from '../lib/format';
import { FREE_SHIPPING_FROM, checkCoupon, computeTotals, linePrice, type CartLine } from '../lib/store';
import ProductImage from './ProductImage';

type Props = {
  lines: CartLine[]; code?: string; setCode: (c?: string) => void; setQty: (key: string, qty: number) => void; remove: (key: string) => void;
  close: () => void; checkout: () => void; openProduct: (id: string) => void;
};

export function CartLineRow({ line, compact, setQty, remove, openProduct }: { line: CartLine; compact?: boolean } & Partial<Pick<Props, 'setQty' | 'remove' | 'openProduct'>>) {
  const p = byId(line.productId);
  if (!p) return null;
  const color = p.colors?.find(c => c.name === line.color);
  const variant = [line.color, line.size].filter(Boolean).join(' · ');
  return (
    <li className="flex gap-3 py-4">
      <button onClick={() => openProduct?.(p.id)} className="shrink-0 overflow-hidden rounded-xl" aria-label={`Ver ${p.name}`} disabled={!openProduct}>
        <ProductImage product={p} color={color} className={compact ? 'h-14 w-14' : 'h-20 w-20'} />
      </button>
      <div className="flex min-w-0 flex-1 flex-col">
        <div className="flex justify-between gap-3">
          <div className="min-w-0">
            <p className="truncate font-semibold text-[#17181C]">{p.name}</p>
            {variant && <p className="text-sm text-[#5B6068]">{variant}</p>}
            {compact && <p className="text-sm text-[#5B6068]">Cantidad: {line.qty}</p>}
          </div>
          <p className="shrink-0 font-semibold tabular text-[#17181C]">{eur(linePrice(line))}</p>
        </div>
        {setQty && remove && (
          <div className="mt-auto flex items-center justify-between pt-2">
            <div className="flex h-9 items-center rounded-full border border-[#D6D7D1]">
              <button onClick={() => setQty(line.key, line.qty - 1)} disabled={line.qty <= 1} aria-label={`Quitar uno de ${p.name}`} className="grid h-9 w-9 place-items-center text-[#17181C] disabled:text-[#B9BBB5]"><Minus size={14} /></button>
              <span className="w-5 text-center text-sm font-semibold tabular text-[#17181C]">{line.qty}</span>
              <button onClick={() => setQty(line.key, line.qty + 1)} disabled={line.qty >= Math.min(10, p.stock)} aria-label={`Añadir uno de ${p.name}`} className="grid h-9 w-9 place-items-center text-[#17181C] disabled:text-[#B9BBB5]"><Plus size={14} /></button>
            </div>
            <button onClick={() => remove(line.key)} className="flex items-center gap-1 text-sm text-[#5B6068] hover:text-[#C2252B]"><Trash2 size={14} />Eliminar</button>
          </div>
        )}
      </div>
    </li>
  );
}

export default function CartDrawer({ lines, code, setCode, setQty, remove, close, checkout, openProduct }: Props) {
  const [input, setInput] = useState('');
  const [error, setError] = useState('');
  const t = computeTotals(lines, code);
  const missing = FREE_SHIPPING_FROM - (t.subtotal - t.discount);
  const count = lines.reduce((s, l) => s + l.qty, 0);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && close();
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [close]);

  const apply = () => {
    if (!input.trim()) { setError('Escribe un código.'); return; }
    const r = checkCoupon(input, t.subtotal);
    if (!r.ok) { setError(r.error); return; }
    setCode(r.coupon.code); setInput(''); setError('');
  };

  return (
    <div className="fixed inset-0 z-50" role="dialog" aria-modal="true" aria-label="Carrito">
      <div className="fade-enter absolute inset-0 bg-[#17181C]/40" onClick={close} />
      <aside className="drawer-enter absolute right-0 top-0 flex h-full w-full max-w-[440px] flex-col bg-[#F4F4F1] shadow-2xl">
        <div className="flex items-center justify-between border-b border-[#E4E5E0] px-5 py-4">
          <h2 className="font-display text-xl font-semibold text-[#17181C]">Tu carrito <span className="text-[#5B6068]">({count})</span></h2>
          <button onClick={close} aria-label="Cerrar carrito" className="grid h-10 w-10 place-items-center rounded-full text-[#17181C] hover:bg-[#E9EAE5]"><X size={20} /></button>
        </div>

        {lines.length === 0 ? (
          <div className="flex flex-1 flex-col items-center justify-center px-8 text-center">
            <span className="grid h-16 w-16 place-items-center rounded-full bg-[#F2C230]"><ShoppingBag size={26} className="text-[#17181C]" /></span>
            <p className="mt-4 font-display text-xl font-semibold text-[#17181C]">Tu carrito está vacío</p>
            <p className="mt-1 text-sm text-[#5B6068]">Guarda aquí lo que te guste y te avisamos del envío gratis a partir de 60 €.</p>
            <button onClick={close} className="mt-5 rounded-full bg-[#17181C] px-5 py-2.5 text-sm font-semibold text-white">Seguir comprando</button>
          </div>
        ) : (
          <>
            <div className="px-5 pt-4">
              <p className="text-sm text-[#3A3D43]">{t.freeShipping ? 'Tu pedido tiene envío gratis.' : <>Te faltan <b className="tabular text-[#17181C]">{eurExact(missing)}</b> para el envío gratis.</>}</p>
              <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#E4E5E0]">
                <div className="h-full rounded-full bg-[#2E4BF0] transition-all duration-500" style={{ width: `${t.freeShipping ? 100 : Math.min(100, ((t.subtotal - t.discount) / FREE_SHIPPING_FROM) * 100)}%` }} />
              </div>
            </div>
            <ul className="flex-1 divide-y divide-[#E4E5E0] overflow-y-auto px-5">
              {lines.map(l => <CartLineRow key={l.key} line={l} setQty={setQty} remove={remove} openProduct={id => { close(); openProduct(id); }} />)}
            </ul>
            <div className="border-t border-[#E4E5E0] bg-white px-5 py-4">
              {code ? (
                <div className="flex items-center justify-between rounded-xl bg-[#EEF1FE] px-3 py-2 text-sm">
                  <span className="flex items-center gap-2 font-semibold text-[#2E4BF0]"><Tag size={15} />{code} aplicado</span>
                  <button onClick={() => setCode(undefined)} className="text-[#3A3D43] hover:underline">Quitar</button>
                </div>
              ) : (
                <div>
                  <div className="flex gap-2">
                    <input value={input} onChange={e => { setInput(e.target.value); setError(''); }} onKeyDown={e => e.key === 'Enter' && apply()}
                      placeholder="Código de descuento" aria-label="Código de descuento" aria-invalid={!!error}
                      className="h-11 min-w-0 flex-1 rounded-xl border border-[#D6D7D1] bg-[#F9F9F7] px-3 text-sm uppercase text-[#17181C] outline-none placeholder:normal-case placeholder:text-[#83878D] focus:border-[#2E4BF0]" />
                    <button onClick={apply} className="h-11 rounded-xl border border-[#17181C] px-4 text-sm font-semibold text-[#17181C] hover:bg-[#17181C] hover:text-white">Aplicar</button>
                  </div>
                  {error && <p className="mt-1.5 text-sm text-[#C2252B]" role="alert">{error}</p>}
                </div>
              )}
              <dl className="mt-4 space-y-1.5 text-sm tabular">
                <div className="flex justify-between text-[#3A3D43]"><dt>Subtotal</dt><dd>{eurExact(t.subtotal)}</dd></div>
                {t.discount > 0 && <div className="flex justify-between text-[#2E4BF0]"><dt>Descuento</dt><dd>−{eurExact(t.discount)}</dd></div>}
                <div className="flex justify-between text-[#3A3D43]"><dt>Envío estándar</dt><dd>{t.shipping === 0 ? 'Gratis' : eurExact(t.shipping)}</dd></div>
                <div className="flex justify-between pt-2 text-base font-semibold text-[#17181C]"><dt>Total</dt><dd>{eurExact(t.total)}</dd></div>
              </dl>
              <button onClick={checkout} className="mt-4 h-12 w-full rounded-full bg-[#2E4BF0] font-semibold text-white transition hover:bg-[#2340D8]">Finalizar compra</button>
              <button onClick={close} className="mt-2 h-10 w-full text-sm font-medium text-[#3A3D43] hover:underline">Seguir comprando</button>
            </div>
          </>
        )}
      </aside>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { ArrowDownUp, SlidersHorizontal, X, Truck, RotateCcw, ShieldCheck, SearchX } from 'lucide-react';
import clsx from 'clsx';
import { CATEGORIES, PRODUCTS, type Category, type Product } from '../data/products';
import { IMG } from '../data/images';
import { eur } from '../lib/format';
import ProductCard from './ProductCard';

type Sort = 'relevancia' | 'novedades' | 'precio-asc' | 'precio-desc' | 'valoracion';
const SORTS: { id: Sort; label: string }[] = [
  { id: 'relevancia', label: 'Destacados' }, { id: 'novedades', label: 'Novedades' }, { id: 'precio-asc', label: 'Precio: menor a mayor' },
  { id: 'precio-desc', label: 'Precio: mayor a menor' }, { id: 'valoracion', label: 'Mejor valorados' },
];
const MAX = 250;
const norm = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

type Props = {
  query: string; setQuery: (q: string) => void; category: Category | 'Todo'; setCategory: (c: Category | 'Todo') => void;
  wishlist: string[]; toggleWish: (id: string) => void; openProduct: (id: string) => void;
};

function Hero({ openProduct }: { openProduct: (id: string) => void }) {
  return (
    <section className="grid gap-4 md:grid-cols-[1.15fr_1fr_0.8fr] md:grid-rows-[268px]">
      <div className="flex flex-col justify-between rounded-3xl bg-[#17181C] p-7 text-white">
        <div>
          <p className="text-sm text-[#F2C230]">Colección otoño · 48 piezas nuevas</p>
          <h1 className="mt-2 font-display text-[34px] font-semibold leading-[1.05] md:text-[38px]">Cosas bien hechas para usar cada día.</h1>
          <p className="mt-3 max-w-sm text-[15px] leading-relaxed text-white/70">Auriculares, relojes, cámaras y ropa elegidos para durar. Envío en 24–72 h desde Madrid.</p>
        </div>
        <div className="mt-6 flex flex-wrap gap-2">
          <button onClick={() => openProduct('eco-anc')} className="rounded-full bg-white px-5 py-2.5 text-sm font-semibold text-[#17181C] transition hover:bg-[#F2C230]">Ver auriculares Eco</button>
          <button onClick={() => document.getElementById('catalogo')?.scrollIntoView({ behavior: 'smooth' })} className="rounded-full border border-white/30 px-5 py-2.5 text-sm font-semibold transition hover:bg-white/10">Explorar catálogo</button>
        </div>
      </div>
      <button onClick={() => openProduct('eco-anc')} className="group relative hidden overflow-hidden rounded-3xl bg-[#F2C230] text-left md:block" aria-label="Auriculares Eco ANC, 249 euros">
        <img src={IMG('prod-audifonos')} alt="Auriculares Eco ANC sobre fondo mostaza" className="absolute inset-0 h-full w-full object-cover transition duration-700 group-hover:scale-105" style={{ objectPosition: '50% 50%' }} />
        <div className="absolute bottom-4 left-4 rounded-2xl bg-white/95 px-4 py-2.5 text-[#17181C] shadow-sm">
          <p className="text-xs text-[#5B6068]">Más vendido</p>
          <p className="font-display font-semibold">Eco ANC · {eur(249)}</p>
        </div>
      </button>
      <div className="hidden min-h-0 grid-rows-2 gap-4 md:grid">
        <button onClick={() => openProduct('pulso-s2')} className="group relative overflow-hidden rounded-3xl bg-[#E7E7E5] text-left" aria-label="Reloj Pulso S2">
          <img src={IMG('prod-reloj')} alt="Reloj Pulso S2 en blanco" className="absolute inset-0 h-full w-full object-cover transition duration-700 group-hover:scale-105" style={{ objectPosition: '30% 50%' }} />
          <span className="absolute left-3 top-3 rounded-full bg-[#2E4BF0] px-2.5 py-1 text-xs font-semibold text-white">Nuevo · Pulso S2</span>
        </button>
        <div className="relative overflow-hidden rounded-3xl bg-[#2B3A55]">
          <img src={IMG('tienda-1')} alt="Interior de la tienda Objeto en Madrid" className="absolute inset-0 h-full w-full object-cover opacity-80" />
          <span className="absolute bottom-3 left-3 right-3 rounded-xl bg-[#17181C]/80 px-3 py-2 text-xs text-white">Tienda física en Fuencarral 43, Madrid</span>
        </div>
      </div>
    </section>
  );
}

export default function Catalog({ query, setQuery, category, setCategory, wishlist, toggleWish, openProduct }: Props) {
  const [maxPrice, setMaxPrice] = useState(MAX);
  const [onlySale, setOnlySale] = useState(false);
  const [inStock, setInStock] = useState(false);
  const [sort, setSort] = useState<Sort>('relevancia');
  const [showFilters, setShowFilters] = useState(false);

  const results = useMemo(() => {
    const q = norm(query.trim());
    const list = PRODUCTS.filter(p =>
      (category === 'Todo' || p.category === category) && p.price <= maxPrice && (!onlySale || !!p.compareAt) && (!inStock || p.stock > 0) &&
      (!q || norm(`${p.name} ${p.category} ${p.short}`).includes(q)));
    const by: Record<Sort, (a: Product, b: Product) => number> = {
      relevancia: (a, b) => b.reviewCount * b.rating - a.reviewCount * a.rating,
      novedades: (a, b) => a.createdDaysAgo - b.createdDaysAgo,
      'precio-asc': (a, b) => a.price - b.price,
      'precio-desc': (a, b) => b.price - a.price,
      valoracion: (a, b) => b.rating - a.rating,
    };
    return [...list].sort(by[sort]);
  }, [query, category, maxPrice, onlySale, inStock, sort]);

  const active = (maxPrice < MAX ? 1 : 0) + (onlySale ? 1 : 0) + (inStock ? 1 : 0);
  const reset = () => { setMaxPrice(MAX); setOnlySale(false); setInStock(false); setCategory('Todo'); setQuery(''); };
  const count = (c: Category | 'Todo') => c === 'Todo' ? PRODUCTS.length : PRODUCTS.filter(p => p.category === c).length;

  const toggle = (label: string, on: boolean, set: (v: boolean) => void) => (
    <label className="flex cursor-pointer items-center justify-between py-1.5 text-sm text-[#17181C]">
      {label}
      <span className={clsx('relative h-6 w-10 rounded-full transition', on ? 'bg-[#2E4BF0]' : 'bg-[#D6D7D1]')}>
        <input type="checkbox" checked={on} onChange={e => set(e.target.checked)} className="peer sr-only" />
        <span className={clsx('absolute top-1 h-4 w-4 rounded-full bg-white shadow transition-all', on ? 'left-5' : 'left-1')} />
      </span>
    </label>
  );

  return (
    <div className="mx-auto max-w-[1240px] px-4 pb-16 pt-6 md:px-8">
