              <span className="sr-only">Ordenar por</span>
              <select value={sort} onChange={e => setSort(e.target.value as Sort)} className="h-full bg-transparent pr-1 font-medium outline-none">
                {SORTS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
              </select>
