          </div>

          {results.length === 0 ? (
            <div className="grid place-items-center rounded-3xl border border-dashed border-[#D6D7D1] px-6 py-20 text-center">
              <SearchX size={32} className="text-[#5B6068]" />
              <p className="mt-3 font-display text-xl font-semibold text-[#17181C]">No encontramos nada así</p>
              <p className="mt-1 max-w-sm text-sm text-[#5B6068]">Prueba con otra palabra o amplía el precio máximo. Tenemos auriculares, relojes, cámaras y ropa.</p>
              <button onClick={reset} className="mt-5 flex items-center gap-1.5 rounded-full bg-[#17181C] px-5 py-2.5 text-sm font-semibold text-white"><X size={15} />Limpiar búsqueda y filtros</button>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-x-4 gap-y-8 sm:grid-cols-3 xl:grid-cols-4 xl:gap-x-5">
              {results.map((p, i) => (
                <ProductCard key={p.id} product={p} eager={i < 4} wished={wishlist.includes(p.id)} onOpen={() => openProduct(p.id)} onToggleWish={() => toggleWish(p.id)} />
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

import { useState, type ChangeEvent, type InputHTMLAttributes } from 'react';
import { Check, ChevronLeft, CreditCard, Lock, Smartphone, UserRound } from 'lucide-react';
import clsx from 'clsx';
import { eurExact } from '../lib/format';
import { SAVED_ADDRESS, SHIPPING_OPTIONS, computeTotals, type Address, type CartLine, type Order, type Shipping } from '../lib/store';
import { CartLineRow } from './CartDrawer';

type Props = { lines: CartLine[]; code?: string; back: () => void; place: (o: Omit<Order, 'id' | 'createdAt' | 'status'>) => void };
type Card = { number: string; exp: string; cvc: string; holder: string };
const STEPS = ['Datos de envío', 'Entrega', 'Pago'];
const EMPTY: Address = { email: '', name: '', phone: '', street: '', city: '', zip: '', province: '' };

function validateAddress(a: Address) {
  const e: Partial<Record<keyof Address, string>> = {};
  if (!/^\S+@\S+\.\S+$/.test(a.email)) e.email = 'Escribe un correo válido, p. ej. nombre@correo.es';
  if (a.name.trim().length < 3) e.name = 'Escribe tu nombre y apellidos';
  if (!/^[67]\d{8}$/.test(a.phone.replace(/\s/g, ''))) e.phone = 'Un móvil español de 9 cifras';
  if (a.street.trim().length < 5) e.street = 'Indica calle, número y piso';
  if (!a.city.trim()) e.city = 'Falta la ciudad';
  if (!/^\d{5}$/.test(a.zip)) e.zip = '5 cifras';
  if (!a.province.trim()) e.province = 'Falta la provincia';
  return e;
}
function validateCard(c: Card) {
  const e: Partial<Record<keyof Card, string>> = {};
  if (c.number.replace(/\s/g, '').length !== 16) e.number = 'La tarjeta tiene 16 cifras';
  const [mm, yy] = c.exp.split('/').map(Number);
  const now = new Date();
  if (!mm || mm > 12 || !yy || 2000 + yy < now.getFullYear() || (2000 + yy === now.getFullYear() && mm < now.getMonth() + 1)) e.exp = 'Fecha MM/AA no válida';
  if (!/^\d{3}$/.test(c.cvc)) e.cvc = '3 cifras';
  if (c.holder.trim().length < 3) e.holder = 'Como aparece en la tarjeta';
  return e;
}

function Field({ label, error, className, ...rest }: { label: string; error?: string; className?: string } & InputHTMLAttributes<HTMLInputElement>) {
  return (
    <label className={clsx('block', className)}>
      <span className="text-sm font-medium text-[#3A3D43]">{label}</span>
      <input {...rest} aria-invalid={!!error}
        className={clsx('mt-1 h-11 w-full rounded-xl border bg-white px-3 text-[15px] text-[#17181C] outline-none transition placeholder:text-[#9A9DA2] focus:border-[#2E4BF0]',
          error ? 'border-[#C2252B]' : 'border-[#D6D7D1]')} />
      {error && <span className="mt-1 block text-[13px] text-[#C2252B]">{error}</span>}
    </label>
  );
}

export default function Checkout({ lines, code, back, place }: Props) {
  const [step, setStep] = useState(0);
  const [addr, setAddr] = useState<Address>(EMPTY);
  const [aErr, setAErr] = useState<ReturnType<typeof validateAddress>>({});
  const [shipping, setShipping] = useState<Shipping>('estandar');
  const [payment, setPayment] = useState<'tarjeta' | 'bizum'>('tarjeta');
  const [card, setCard] = useState<Card>({ number: '', exp: '', cvc: '', holder: '' });
  const [cErr, setCErr] = useState<ReturnType<typeof validateCard>>({});
  const [sending, setSending] = useState(false);
  const t = computeTotals(lines, code, shipping);

  const setA = (k: keyof Address) => (e: ChangeEvent<HTMLInputElement>) => { setAddr(a => ({ ...a, [k]: e.target.value })); setAErr(x => ({ ...x, [k]: undefined })); };
  const setC = (k: keyof Card, fmt?: (v: string) => string) => (e: ChangeEvent<HTMLInputElement>) => {
    const v = fmt ? fmt(e.target.value) : e.target.value; setCard(c => ({ ...c, [k]: v })); setCErr(x => ({ ...x, [k]: undefined }));
  };

  const nextFromAddress = () => { const e = validateAddress(addr); setAErr(e); if (Object.keys(e).length === 0) setStep(1); };
  const confirm = () => {
    if (payment === 'tarjeta') { const e = validateCard(card); setCErr(e); if (Object.keys(e).length) return; }
    setSending(true);
    setTimeout(() => place({ lines, address: addr, shipping, payment, code, totals: t }), 450);
  };

  if (lines.length === 0) {
    return (
      <div className="mx-auto max-w-md px-4 py-24 text-center">
        <p className="font-display text-2xl font-semibold text-[#17181C]">No hay nada que pagar todavía</p>
        <p className="mt-2 text-[#5B6068]">Añade algún producto al carrito para empezar el pedido.</p>
        <button onClick={back} className="mt-6 rounded-full bg-[#17181C] px-5 py-2.5 font-semibold text-white">Volver a la tienda</button>
      </div>
    );
  }

  return (
    <div className="mx-auto grid max-w-[1240px] gap-8 px-4 pb-16 pt-6 md:px-8 lg:grid-cols-[1fr_400px] lg:gap-12">
      <div>
        <button onClick={step === 0 ? back : () => setStep(s => s - 1)} className="flex items-center gap-1 text-sm font-medium text-[#17181C] hover:underline">
          <ChevronLeft size={16} />{step === 0 ? 'Volver a la tienda' : `Volver a ${STEPS[step - 1].toLowerCase()}`}
        </button>
        <h1 className="mt-4 font-display text-[32px] font-semibold text-[#17181C]">Finalizar compra</h1>
        <ol className="mt-5 flex gap-2" aria-label="Pasos">
          {STEPS.map((s, i) => (
            <li key={s} className="flex flex-1 flex-col gap-2" aria-current={i === step ? 'step' : undefined}>
              <span className={clsx('h-1 rounded-full transition-colors', i <= step ? 'bg-[#2E4BF0]' : 'bg-[#DCDDD7]')} />
              <span className={clsx('flex items-center gap-1.5 text-sm', i === step ? 'font-semibold text-[#17181C]' : 'text-[#5B6068]')}>
                {i < step && <Check size={14} className="text-[#2E4BF0]" />}{s}
              </span>
            </li>
          ))}
        </ol>

        <div key={step} className="fade-enter mt-8">
          {step === 0 && (
            <section>
              <div className="flex flex-wrap items-center justify-between gap-3">
                <h2 className="font-display text-xl font-semibold text-[#17181C]">¿A dónde lo enviamos?</h2>
                <button onClick={() => { setAddr(SAVED_ADDRESS); setAErr({}); }} className="flex items-center gap-2 rounded-full border border-[#D6D7D1] bg-white px-4 py-2 text-sm font-medium text-[#17181C] hover:border-[#17181C]">
                  <UserRound size={15} />Usar mis datos guardados
                </button>
              </div>
              <div className="mt-5 grid gap-4 sm:grid-cols-6">
                <Field label="Correo electrónico" type="email" autoComplete="email" value={addr.email} onChange={setA('email')} error={aErr.email} className="sm:col-span-3" placeholder="nombre@correo.es" />
                <Field label="Móvil" inputMode="tel" autoComplete="tel" value={addr.phone} onChange={setA('phone')} error={aErr.phone} className="sm:col-span-3" placeholder="612 345 678" />
                <Field label="Nombre y apellidos" autoComplete="name" value={addr.name} onChange={setA('name')} error={aErr.name} className="sm:col-span-6" />
                <Field label="Dirección" autoComplete="street-address" value={addr.street} onChange={setA('street')} error={aErr.street} className="sm:col-span-6" placeholder="Calle, número, piso y puerta" />
                <Field label="Código postal" inputMode="numeric" maxLength={5} value={addr.zip} onChange={setA('zip')} error={aErr.zip} className="sm:col-span-2" />
                <Field label="Ciudad" value={addr.city} onChange={setA('city')} error={aErr.city} className="sm:col-span-2" />
                <Field label="Provincia" value={addr.province} onChange={setA('province')} error={aErr.province} className="sm:col-span-2" />
              </div>
              <button onClick={nextFromAddress} className="mt-7 h-12 w-full rounded-full bg-[#2E4BF0] px-8 font-semibold text-white hover:bg-[#2340D8] sm:w-auto">Continuar a la entrega</button>
            </section>
          )}

          {step === 1 && (
            <section>
              <h2 className="font-display text-xl font-semibold text-[#17181C]">¿Cómo lo quieres recibir?</h2>
              <p className="mt-1 text-sm text-[#5B6068]">Enviamos a {addr.street}, {addr.zip} {addr.city}.</p>
              <div className="mt-5 space-y-3" role="radiogroup">
                {SHIPPING_OPTIONS.map(o => {
                  const price = o.id === 'estandar' && computeTotals(lines, code).freeShipping ? 0 : o.price;
                  return (
                    <button key={o.id} role="radio" aria-checked={shipping === o.id} onClick={() => setShipping(o.id)}
                      className={clsx('flex w-full items-center gap-4 rounded-2xl border bg-white p-4 text-left transition', shipping === o.id ? 'border-[#2E4BF0] ring-1 ring-[#2E4BF0]' : 'border-[#D6D7D1] hover:border-[#8E9198]')}>
                      <span className={clsx('grid h-5 w-5 shrink-0 place-items-center rounded-full border-2', shipping === o.id ? 'border-[#2E4BF0]' : 'border-[#B9BBB5]')}>
                        {shipping === o.id && <span className="h-2.5 w-2.5 rounded-full bg-[#2E4BF0]" />}
                      </span>
                      <span className="flex-1"><span className="block font-semibold text-[#17181C]">{o.name}</span><span className="text-sm text-[#5B6068]">{o.detail}</span></span>
                      <span className="font-semibold tabular text-[#17181C]">{price === 0 ? 'Gratis' : eurExact(price)}</span>
                    </button>
                  );
                })}
              </div>
              <button onClick={() => setStep(2)} className="mt-7 h-12 w-full rounded-full bg-[#2E4BF0] px-8 font-semibold text-white hover:bg-[#2340D8] sm:w-auto">Continuar al pago</button>
            </section>
          )}

          {step === 2 && (
            <section>
              <h2 className="font-display text-xl font-semibold text-[#17181C]">Pago</h2>
              <p className="mt-1 flex items-center gap-1.5 text-sm text-[#5B6068]"><Lock size={14} />Tienda de demostración: no se realiza ningún cobro.</p>
              <div className="mt-5 grid grid-cols-2 gap-3">
                {([['tarjeta', 'Tarjeta', CreditCard], ['bizum', 'Bizum', Smartphone]] as const).map(([id, label, Icon]) => (
                  <button key={id} onClick={() => setPayment(id)} aria-pressed={payment === id}
                    className={clsx('flex h-14 items-center justify-center gap-2 rounded-2xl border bg-white font-semibold text-[#17181C] transition', payment === id ? 'border-[#2E4BF0] ring-1 ring-[#2E4BF0]' : 'border-[#D6D7D1] hover:border-[#8E9198]')}>
                    <Icon size={18} />{label}
                  </button>
                ))}
              </div>
              {payment === 'tarjeta' ? (
                <div className="mt-5 grid gap-4 sm:grid-cols-4">
                  <Field label="Número de tarjeta" inputMode="numeric" placeholder="4242 4242 4242 4242" value={card.number} error={cErr.number} className="sm:col-span-4"
                    onChange={setC('number', v => v.replace(/\D/g, '').slice(0, 16).replace(/(\d{4})(?=\d)/g, '$1 '))} />
                  <Field label="Caducidad" placeholder="MM/AA" value={card.exp} error={cErr.exp} className="sm:col-span-1"
                    onChange={setC('exp', v => { const d = v.replace(/\D/g, '').slice(0, 4); return d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}` : d; })} />
                  <Field label="CVC" inputMode="numeric" placeholder="123" value={card.cvc} error={cErr.cvc} className="sm:col-span-1" onChange={setC('cvc', v => v.replace(/\D/g, '').slice(0, 3))} />
                  <Field label="Titular" value={card.holder} error={cErr.holder} className="sm:col-span-2" onChange={setC('holder')} />
                </div>
              ) : (
                <p className="mt-5 rounded-2xl bg-white p-4 text-sm text-[#3A3D43]">Te enviaremos una solicitud de pago al <b className="text-[#17181C]">{addr.phone}</b>. Acéptala en la app de tu banco en los próximos 5 minutos.</p>
              )}
              <button onClick={confirm} disabled={sending} className="mt-7 flex h-12 w-full items-center justify-center gap-2 rounded-full bg-[#2E4BF0] px-8 font-semibold text-white hover:bg-[#2340D8] disabled:opacity-70 sm:w-auto">
                {sending ? <><span className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white" />Procesando…</> : `Confirmar pedido · ${eurExact(t.total)}`}
              </button>
            </section>
          )}
        </div>
      </div>

      <aside className="h-fit rounded-3xl bg-white p-6 lg:sticky lg:top-36">
        <h2 className="font-display text-lg font-semibold text-[#17181C]">Resumen del pedido</h2>
        <ul className="divide-y divide-[#E4E5E0]">{lines.map(l => <CartLineRow key={l.key} line={l} compact />)}</ul>
        <dl className="mt-2 space-y-1.5 border-t border-[#E4E5E0] pt-4 text-sm tabular">
          <div className="flex justify-between text-[#3A3D43]"><dt>Subtotal</dt><dd>{eurExact(t.subtotal)}</dd></div>
          {t.discount > 0 && <div className="flex justify-between text-[#2E4BF0]"><dt>Descuento {code}</dt><dd>−{eurExact(t.discount)}</dd></div>}
          <div className="flex justify-between text-[#3A3D43]"><dt>Envío · {SHIPPING_OPTIONS.find(o => o.id === shipping)!.name}</dt><dd>{t.shipping === 0 ? 'Gratis' : eurExact(t.shipping)}</dd></div>
          <div className="flex justify-between pt-2 text-lg font-semibold text-[#17181C]"><dt>Total</dt><dd>{eurExact(t.total)}</dd></div>
          <p className="text-xs text-[#5B6068]">IVA incluido</p>
        </dl>
      </aside>
    </div>
  );
}

