        <div className="ml-auto flex items-center gap-1 md:ml-0">
          <button onClick={p.onOrders} className={clsx(iconBtn, p.active === 'pedidos' && 'bg-[#E9EAE5]')} aria-label="Mis pedidos"><Package size={20} /></button>
          <button onClick={p.onWishlist} className={clsx(iconBtn, p.active === 'deseos' && 'bg-[#E9EAE5]')} ><Heart size={20} /><span className="sr-only">Lista de deseos</span><Count n={p.wishCount} /></button>
          <button onClick={p.onCart} className={iconBtn} ><ShoppingBag size={20} /><span className="sr-only">Carrito</span><Count n={p.cartCount} /></button>
        </div>
      </div>
      <div className="px-4 pb-3 md:hidden">
        <SearchBox query={p.query} setQuery={p.setQuery} />
      </div>
    </header>
  );
}

import { Check, CircleCheck, MapPin, Package, Truck } from 'lucide-react';
import clsx from 'clsx';
import { deliveryDate, eurExact, longDate, relativeDays, shortDate } from '../lib/format';
import { SHIPPING_OPTIONS, type Order } from '../lib/store';
import { CartLineRow } from './CartDrawer';

const STAGES = ['Confirmado', 'Preparando', 'Enviado', 'Entregado'];
const stageIndex = (o: Order) => (o.status === 'Entregado' ? 3 : o.status === 'Enviado' ? 2 : 0);

function Timeline({ order }: { order: Order }) {
  const at = stageIndex(order);
  return (
    <ol className="grid grid-cols-4 gap-2">
      {STAGES.map((s, i) => (
        <li key={s} className="flex flex-col gap-2">
          <span className={clsx('h-1.5 rounded-full', i <= at ? 'bg-[#2E4BF0]' : 'bg-[#E4E5E0]')} />
          <span className={clsx('text-xs sm:text-sm', i <= at ? 'font-semibold text-[#17181C]' : 'text-[#5B6068]')}>{s}</span>
        </li>
      ))}
    </ol>
  );
}

export function OrderCard({ order, open }: { order: Order; open?: boolean }) {
  const created = new Date(order.createdAt);
  const eta = deliveryDate(order.shipping === 'expres' ? 1 : 3, created);
  const ship = SHIPPING_OPTIONS.find(s => s.id === order.shipping)!;
  return (
    <article className="rounded-3xl bg-white p-5 sm:p-6">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <p className="font-display text-lg font-semibold text-[#17181C]">Pedido {order.id}</p>
          <p className="text-sm text-[#5B6068]">Realizado {relativeDays(order.createdAt)} · {longDate(created)}</p>
        </div>
        <span className={clsx('flex items-center gap-1.5 rounded-full px-3 py-1 text-sm font-semibold',
          order.status === 'Entregado' ? 'bg-[#E3F2E8] text-[#1D6B3A]' : 'bg-[#EEF1FE] text-[#2E4BF0]')}>
          {order.status === 'Entregado' ? <CircleCheck size={15} /> : <Package size={15} />}{order.status}
        </span>
      </div>
      <div className="mt-5"><Timeline order={order} /></div>
      <p className="mt-3 flex items-center gap-2 text-sm text-[#3A3D43]">
        <Truck size={16} className="text-[#2E4BF0]" />
        {order.status === 'Entregado' ? `Entregado el ${shortDate(eta)}` : order.shipping === 'tienda' ? 'Listo para recoger en Fuencarral 43 en 2 horas' : `Entrega estimada: ${shortDate(eta)} · ${ship.name}`}
      </p>
      {open && (
        <div className="mt-5 grid gap-6 border-t border-[#E4E5E0] pt-2 md:grid-cols-[1fr_260px]">
          <ul className="divide-y divide-[#E4E5E0]">{order.lines.map(l => <CartLineRow key={l.key} line={l} compact />)}</ul>
          <div className="space-y-4 pt-4 text-sm">
            <div className="flex gap-2 text-[#3A3D43]"><MapPin size={16} className="mt-0.5 shrink-0 text-[#17181C]" />
              <p><b className="text-[#17181C]">{order.address.name}</b><br />{order.address.street}<br />{order.address.zip} {order.address.city}, {order.address.province}</p></div>
            <dl className="space-y-1 tabular">
              <div className="flex justify-between text-[#3A3D43]"><dt>Subtotal</dt><dd>{eurExact(order.totals.subtotal)}</dd></div>
              {order.totals.discount > 0 && <div className="flex justify-between text-[#2E4BF0]"><dt>Descuento</dt><dd>−{eurExact(order.totals.discount)}</dd></div>}
              <div className="flex justify-between text-[#3A3D43]"><dt>Envío</dt><dd>{order.totals.shipping ? eurExact(order.totals.shipping) : 'Gratis'}</dd></div>
              <div className="flex justify-between pt-1 font-semibold text-[#17181C]"><dt>Total ({order.payment === 'bizum' ? 'Bizum' : 'tarjeta'})</dt><dd>{eurExact(order.totals.total)}</dd></div>
            </dl>
          </div>
        </div>
      )}
    </article>
  );
}

export function Confirmation({ order, back, toOrders }: { order: Order; back: () => void; toOrders: () => void }) {
  const first = order.address.name.split(' ')[0];
  return (
    <div className="mx-auto max-w-[880px] px-4 pb-16 pt-10 md:px-8">
      <div className="flex flex-col items-center text-center">
        <span className="grid h-16 w-16 place-items-center rounded-full bg-[#2E4BF0] text-white"><Check size={30} strokeWidth={2.5} /></span>
        <h1 className="mt-5 font-display text-[34px] font-semibold leading-tight text-[#17181C]">Gracias, {first}. Tu pedido está confirmado.</h1>
        <p className="mt-2 max-w-lg text-[#3A3D43]">Te hemos enviado el resumen a <b className="text-[#17181C]">{order.address.email}</b>. Te avisaremos por SMS cuando salga del almacén.</p>
        <div className="mt-6 flex flex-wrap justify-center gap-2">
          <button onClick={back} className="rounded-full bg-[#17181C] px-5 py-2.5 text-sm font-semibold text-white">Seguir comprando</button>
          <button onClick={toOrders} className="rounded-full border border-[#D6D7D1] bg-white px-5 py-2.5 text-sm font-semibold text-[#17181C]">Ver mis pedidos</button>
        </div>
      </div>
      <div className="mt-10"><OrderCard order={order} open /></div>
    </div>
  );
}

export default function Orders({ orders, back }: { orders: Order[]; back: () => void }) {
  return (
    <div className="mx-auto max-w-[880px] px-4 pb-16 pt-8 md:px-8">
      <h1 className="font-display text-[32px] font-semibold text-[#17181C]">Mis pedidos</h1>
      <p className="mt-1 text-[#5B6068]">Sigue tus envíos y consulta lo que has comprado.</p>
      {orders.length === 0 ? (
        <div className="mt-8 rounded-3xl border border-dashed border-[#D6D7D1] px-6 py-16 text-center">
          <p className="text-[#3A3D43]">Aún no has hecho ningún pedido.</p>
          <button onClick={back} className="mt-4 rounded-full bg-[#17181C] px-5 py-2.5 text-sm font-semibold text-white">Ir a la tienda</button>
        </div>
      ) : (
        <div className="mt-8 space-y-4">{orders.map((o, i) => <OrderCard key={o.id} order={o} open={i === 0} />)}</div>
      )}
    </div>
  );
}

import { Heart, Star } from 'lucide-react';
import clsx from 'clsx';
import type { Product } from '../data/products';
import { eur } from '../lib/format';
import ProductImage from './ProductImage';

type Props = { product: Product; wished: boolean; onOpen: () => void; onToggleWish: () => void; eager?: boolean };

export default function ProductCard({ product: p, wished, onOpen, onToggleWish, eager }: Props) {
  const soldOut = p.stock === 0;
  return (
    <article className="group">
      <div className="relative">
        <button onClick={onOpen} aria-label={`Ver ${p.name}`} className="block w-full overflow-hidden rounded-2xl">
          <ProductImage product={p} color={p.colors?.[0]} eager={eager} className={clsx('aspect-[4/5] transition-transform duration-500 group-hover:scale-[1.02]', soldOut && 'opacity-60')} />
        </button>
        <div className="pointer-events-none absolute left-3 top-3 flex flex-col items-start gap-1.5">
          {soldOut ? (
            <span className="rounded-full bg-white px-2.5 py-1 text-xs font-semibold text-[#17181C]">Agotado</span>
          ) : p.badge ? (
            <span className={clsx('rounded-full px-2.5 py-1 text-xs font-semibold', p.badge === 'Nuevo' ? 'bg-[#2E4BF0] text-white' : 'bg-white text-[#17181C]')}>{p.badge}</span>
          ) : null}
          {p.compareAt && !soldOut && (
            <span className="rounded-full bg-[#17181C] px-2.5 py-1 text-xs font-semibold text-white">−{Math.round((1 - p.price / p.compareAt) * 100)} %</span>
          )}
        </div>
        <button
          onClick={onToggleWish}
          aria-label={wished ? `Quitar ${p.name} de deseos` : `Guardar ${p.name} en deseos`}
          aria-pressed={wished}
          className="absolute right-3 top-3 grid h-9 w-9 place-items-center rounded-full bg-white/90 text-[#17181C] shadow-sm backdrop-blur transition hover:scale-105"
        >
          <Heart size={17} className={clsx(wished && 'fill-[#E5484D] text-[#E5484D]')} />
        </button>
      </div>
      <button onClick={onOpen} className="mt-3 block w-full text-left">
        <h3 className="truncate font-display text-[16px] font-semibold leading-snug text-[#17181C]">{p.name}</h3>
        <div className="mt-0.5 tabular">
          <span className="font-semibold text-[#17181C]">{eur(p.price)}</span>
          {p.compareAt && <span className="ml-1.5 text-sm text-[#5B6068] line-through">{eur(p.compareAt)}</span>}
        </div>
        <div className="mt-1 flex items-center justify-between gap-2 text-[13px] text-[#5B6068]">
          <span className="flex items-center gap-1">
            <Star size={12} className="fill-[#17181C] text-[#17181C]" />
            <span className="tabular text-[#17181C]">{p.rating.toLocaleString('es-ES')}</span>
            <span>({p.reviewCount})</span>
          </span>
          {p.colors && (
            <span className="flex -space-x-1" aria-label={`${p.colors.length} colores`}>
              {p.colors.map(c => <span key={c.name} className="h-3.5 w-3.5 rounded-full border-2 border-[#F4F4F1]" style={{ background: c.swatch }} />)}
            </span>
          )}
        </div>
      </button>
    </article>
  );
}

import clsx from 'clsx';
import { IMG } from '../data/images';
import type { Color, Frame, Product } from '../data/products';

type Props = { product: Product; frame?: Frame; color?: Color; className?: string; eager?: boolean; zoomFactor?: number };

/** Foto de producto: mismo archivo con distintos encuadres, tinte de color para las variantes. */
export default function ProductImage({ product, frame = product.frames[0], color, className, eager, zoomFactor = 1 }: Props) {
  const pos = frame.pos ?? '50% 50%';
  const isGift = product.id === 'tarjeta';
  return (
    <div className={clsx('relative overflow-hidden', className)} style={{ background: color?.tint ?? product.bg }}>
      <img
        src={IMG(frame.img)}
        alt={`${product.name}${color ? ` en ${color.name.toLowerCase()}` : ''}`}
        loading={eager ? 'eager' : 'lazy'}
        className="absolute inset-0 h-full w-full object-cover transition-[filter,transform] duration-500"
        style={{ objectPosition: pos, transform: `scale(${Math.max(1, (frame.zoom ?? 1) * zoomFactor)})`, transformOrigin: pos, filter: color?.filter }}
      />
      {color?.tint && <div className="pointer-events-none absolute inset-0 mix-blend-multiply" style={{ background: color.tint }} />}
      {isGift && (
        <div className="absolute inset-0 flex items-center justify-center bg-[#17181C]/45 p-[8%]">
          <div className="flex aspect-[1.6] w-full max-w-[340px] flex-col justify-between rounded-2xl bg-[#2E4BF0] p-[7%] text-white shadow-2xl">
            <div className="flex items-center justify-between">
              <span className="font-display text-xl font-semibold">objeto</span>
              <span className="h-6 w-6 rounded-full bg-[#F2C230]" />
            </div>
            <div>
              <p className="text-xs text-white/75">Tarjeta regalo</p>
              <p className="font-display text-3xl font-semibold">50 €</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, type ReactNode } from 'react';
import { ChevronDown, ChevronLeft, Heart, Minus, Plus, ShoppingBag, Star, Store, Truck } from 'lucide-react';
import clsx from 'clsx';
import { PRODUCTS, REVIEWS, byId } from '../data/products';
import { IMG } from '../data/images';
import { deliveryDate, eur, shortDate } from '../lib/format';
import ProductImage from './ProductImage';
import ProductCard from './ProductCard';

type Props = {
  id: string; wishlist: string[]; toggleWish: (id: string) => void; openProduct: (id: string) => void; back: () => void;
  addToCart: (productId: string, qty: number, color?: string, size?: string) => void;
};

function Stars({ value, size = 14 }: { value: number; size?: number }) {
  return (
    <span className="flex" aria-label={`${value} de 5 estrellas`}>
      {[1, 2, 3, 4, 5].map(i => <Star key={i} size={size} className={i <= Math.round(value) ? 'fill-[#17181C] text-[#17181C]' : 'text-[#B9BBB5]'} />)}
    </span>
  );
}

export default function ProductPage({ id, wishlist, toggleWish, openProduct, back, addToCart }: Props) {
  const p = byId(id)!;
  const [frame, setFrame] = useState(0);
  const [color, setColor] = useState(p.colors?.[0]);
  const [size, setSize] = useState<string | undefined>(p.sizes?.length === 1 ? p.sizes[0] : undefined);
  const [qty, setQty] = useState(1);
  const [sizeError, setSizeError] = useState(false);
  const [open, setOpen] = useState<string | null>('Descripción');
  const wished = wishlist.includes(p.id);
  const soldOut = p.stock === 0;
  const maxQty = Math.min(p.stock, 10);
  const related = PRODUCTS.filter(x => x.id !== p.id && (x.category === p.category || x.category === 'Accesorios')).slice(0, 4);

  const add = () => {
    if (p.sizes && !size) { setSizeError(true); return; }
    addToCart(p.id, qty, color?.name, size);
  };

  const sections: [string, ReactNode][] = [
    ['Descripción', <p className="leading-relaxed">{p.description}</p>],
    ['Especificaciones', (
      <dl className="divide-y divide-[#E4E5E0]">
        {p.specs.map(([k, v]) => <div key={k} className="flex justify-between gap-4 py-2"><dt>{k}</dt><dd className="text-right font-medium text-[#17181C]">{v}</dd></div>)}
      </dl>
    )],
    ['Envío y devoluciones', <p className="leading-relaxed">Envío estándar gratis a partir de 60 € (4,90 € si no). Exprés en 24 h por 9,90 €. Tienes 30 días para devolverlo gratis desde la web, sin dar explicaciones.</p>],
  ];

  return (
    <div className="mx-auto max-w-[1240px] px-4 pb-16 pt-5 md:px-8">
      <nav className="mb-5 flex items-center gap-1 text-sm text-[#5B6068]" aria-label="Ruta">
        <button onClick={back} className="flex items-center gap-1 rounded-full py-1 pr-2 font-medium text-[#17181C] hover:underline"><ChevronLeft size={16} />Volver a la tienda</button>
        <span>/</span><span>{p.category}</span><span>/</span><span className="truncate text-[#17181C]">{p.name}</span>
      </nav>

      <div className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_440px] lg:gap-14">
        <div className="flex flex-col-reverse gap-3 sm:flex-row">
          <div className="flex gap-3 sm:flex-col" role="tablist" aria-label="Fotos del producto">
            {p.frames.map((f, i) => (
              <button key={i} role="tab" aria-selected={frame === i} aria-label={`Foto ${i + 1}`} onClick={() => setFrame(i)}
                className={clsx('overflow-hidden rounded-xl ring-2 transition', frame === i ? 'ring-[#17181C]' : 'ring-transparent hover:ring-[#C9CAC4]')}>
                <ProductImage product={p} frame={f} color={color} className="h-16 w-16 sm:h-20 sm:w-20" />
              </button>
            ))}
          </div>
          <ProductImage product={p} frame={p.frames[frame]} color={color} eager zoomFactor={0.8} className="aspect-square flex-1 rounded-3xl" />
        </div>

        <div>
          {p.badge && <span className="inline-block rounded-full bg-[#F2C230] px-3 py-1 text-xs font-semibold text-[#17181C]">{p.badge}</span>}
          <h1 className="mt-3 font-display text-[34px] font-semibold leading-tight text-[#17181C] md:text-[40px]">{p.name}</h1>
          <div className="mt-2 flex items-center gap-2 text-sm text-[#5B6068]">
            <Stars value={p.rating} /><span className="tabular text-[#17181C]">{p.rating.toLocaleString('es-ES')}</span><span>· {p.reviewCount} opiniones</span>
          </div>
          <div className="mt-5 flex items-baseline gap-3 tabular">
            <span className="font-display text-3xl font-semibold text-[#17181C]">{eur(p.price)}</span>
            {p.compareAt && <><span className="text-lg text-[#5B6068] line-through">{eur(p.compareAt)}</span>
              <span className="rounded-full bg-[#17181C] px-2.5 py-0.5 text-xs font-semibold text-white">Ahorras {eur(p.compareAt - p.price)}</span></>}
          </div>
          <p className="mt-1 text-xs text-[#5B6068]">IVA incluido</p>
          <p className="mt-4 text-[15px] leading-relaxed text-[#3A3D43]">{p.short}</p>

          {p.colors && color && (
            <fieldset className="mt-6">
              <legend className="text-sm text-[#5B6068]">Color: <span className="font-semibold text-[#17181C]">{color.name}</span></legend>
              <div className="mt-2 flex gap-2">
                {p.colors.map(c => (
                  <button key={c.name} onClick={() => setColor(c)} aria-label={c.name} aria-pressed={color.name === c.name}
                    className={clsx('h-10 w-10 rounded-full border-[3px] border-[#F4F4F1] ring-2 transition', color.name === c.name ? 'ring-[#17181C]' : 'ring-[#D6D7D1] hover:ring-[#8E9198]')}
                    style={{ background: c.swatch }} />
                ))}
              </div>
            </fieldset>
          )}

          {p.sizes && (
            <fieldset className="mt-6">
              <legend className="text-sm text-[#5B6068]">{p.sizeLabel}{size && <>: <span className="font-semibold text-[#17181C]">{size}</span></>}</legend>
              <div className="mt-2 flex flex-wrap gap-2">
                {p.sizes.map(s => (
                  <button key={s} onClick={() => { setSize(s); setSizeError(false); }} aria-pressed={size === s}
                    className={clsx('h-11 min-w-[52px] rounded-xl border px-4 text-sm font-semibold transition',
                      size === s ? 'border-[#17181C] bg-[#17181C] text-white' : 'border-[#D6D7D1] bg-white text-[#17181C] hover:border-[#17181C]')}>{s}</button>
                ))}
              </div>
              {sizeError && <p className="mt-2 text-sm font-medium text-[#C2252B]" role="alert">Elige {p.sizeLabel?.toLowerCase()} para añadirlo al carrito.</p>}
            </fieldset>
          )}

          <div className="mt-7 flex flex-wrap items-center gap-3">
            <div className="flex h-12 items-center rounded-full border border-[#D6D7D1] bg-white">
              <button onClick={() => setQty(q => Math.max(1, q - 1))} disabled={qty <= 1 || soldOut} aria-label="Quitar uno" className="grid h-12 w-11 place-items-center text-[#17181C] disabled:text-[#B9BBB5]"><Minus size={16} /></button>
              <span className="w-6 text-center font-semibold tabular text-[#17181C]" aria-live="polite">{qty}</span>
              <button onClick={() => setQty(q => Math.min(maxQty, q + 1))} disabled={qty >= maxQty || soldOut} aria-label="Añadir uno" className="grid h-12 w-11 place-items-center text-[#17181C] disabled:text-[#B9BBB5]"><Plus size={16} /></button>
            </div>
            <button onClick={add} disabled={soldOut}
              className="flex h-12 flex-1 items-center justify-center gap-2 rounded-full bg-[#2E4BF0] px-6 whitespace-nowrap font-semibold text-white transition hover:bg-[#2340D8] disabled:bg-[#B9BBB5] sm:min-w-[220px]">
              <ShoppingBag size={18} />{soldOut ? 'Agotado' : `Añadir al carrito · ${eur(p.price * qty)}`}
            </button>
            <button onClick={() => toggleWish(p.id)} aria-pressed={wished} aria-label={wished ? 'Quitar de deseos' : 'Guardar en deseos'}
              className="grid h-12 w-12 place-items-center rounded-full border border-[#D6D7D1] bg-white text-[#17181C] transition hover:border-[#17181C]">
              <Heart size={19} className={clsx(wished && 'fill-[#E5484D] text-[#E5484D]')} />
            </button>
          </div>
          {!soldOut && p.stock <= 6 && <p className="mt-3 text-sm font-medium text-[#9A5B00]">Solo quedan {p.stock} unidades</p>}

          <ul className="mt-6 space-y-3 rounded-2xl bg-white p-4 text-sm text-[#3A3D43]">
            <li className="flex gap-3"><Truck size={18} className="shrink-0 text-[#2E4BF0]" />
              <span>Pídelo hoy y llega entre el <b className="text-[#17181C]">{shortDate(deliveryDate(2))}</b> y el <b className="text-[#17181C]">{shortDate(deliveryDate(4))}</b></span></li>
            <li className="flex gap-3"><Store size={18} className="shrink-0 text-[#2E4BF0]" /><span>Recógelo gratis en Fuencarral 43, Madrid, en 2 horas</span></li>
          </ul>

          <div className="mt-6 border-t border-[#E4E5E0]">
            {sections.map(([title, body]) => (
              <div key={title} className="border-b border-[#E4E5E0]">
                <button onClick={() => setOpen(o => o === title ? null : title)} aria-expanded={open === title}
                  className="flex w-full items-center justify-between py-4 text-left font-semibold text-[#17181C]">
                  {title}<ChevronDown size={18} className={clsx('transition-transform', open === title && 'rotate-180')} />
                </button>
                {open === title && <div className="fade-enter pb-4 text-sm text-[#3A3D43]">{body}</div>}
              </div>
            ))}
          </div>
        </div>
      </div>

      <section className="mt-16">
        <h2 className="font-display text-2xl font-semibold text-[#17181C]">Lo que dicen quienes lo tienen</h2>
        <div className="mt-5 grid gap-4 md:grid-cols-3">
          {REVIEWS.map(r => (
            <figure key={r.name} className="rounded-2xl bg-white p-5">
              <Stars value={r.rating} size={13} />
              <blockquote className="mt-3 text-[15px] leading-relaxed text-[#3A3D43]">{r.text}</blockquote>
              <figcaption className="mt-4 flex items-center gap-3 text-sm">
                <img src={IMG(r.avatar)} alt={`Foto de ${r.name}`} loading="lazy" className="h-9 w-9 rounded-full bg-[#E4E5E0] object-cover" />
                <span><span className="block font-semibold text-[#17181C]">{r.name}</span><span className="text-[#5B6068]">Compra verificada · {r.when}</span></span>
              </figcaption>
            </figure>
          ))}
        </div>
      </section>

      <section className="mt-16">
        <h2 className="font-display text-2xl font-semibold text-[#17181C]">También te puede gustar</h2>
        <div className="mt-5 grid grid-cols-2 gap-x-4 gap-y-8 md:grid-cols-4">
          {related.map(r => <ProductCard key={r.id} product={r} wished={wishlist.includes(r.id)} onOpen={() => openProduct(r.id)} onToggleWish={() => toggleWish(r.id)} />)}
        </div>
      </section>
    </div>
  );
}

import { Heart, ShoppingBag, Trash2 } from 'lucide-react';
import { byId } from '../data/products';
import { eur } from '../lib/format';
import ProductImage from './ProductImage';

type Props = {
  ids: string[]; toggleWish: (id: string) => void; openProduct: (id: string) => void; back: () => void;
  quickAdd: (id: string) => void;
};

export default function Wishlist({ ids, toggleWish, openProduct, back, quickAdd }: Props) {
  const items = ids.map(byId).filter(Boolean) as NonNullable<ReturnType<typeof byId>>[];
  return (
    <div className="mx-auto max-w-[1240px] px-4 pb-16 pt-8 md:px-8">
      <h1 className="font-display text-[32px] font-semibold text-[#17181C]">Lista de deseos</h1>
      <p className="mt-1 text-[#5B6068]">{items.length === 0 ? 'Todavía no has guardado nada.' : `${items.length} ${items.length === 1 ? 'producto guardado' : 'productos guardados'} en este dispositivo.`}</p>

      {items.length === 0 ? (
        <div className="mt-8 grid place-items-center rounded-3xl border border-dashed border-[#D6D7D1] px-6 py-20 text-center">
          <Heart size={30} className="text-[#5B6068]" />
          <p className="mt-3 max-w-sm text-[#3A3D43]">Pulsa el corazón en cualquier producto para guardarlo aquí y comparar con calma.</p>
          <button onClick={back} className="mt-5 rounded-full bg-[#17181C] px-5 py-2.5 text-sm font-semibold text-white">Ver el catálogo</button>
        </div>
      ) : (
        <ul className="mt-8 grid gap-4 md:grid-cols-2">
          {items.map(p => {
            const needsChoice = !!p.sizes;
            return (
              <li key={p.id} className="flex gap-4 rounded-3xl bg-white p-3 pr-5">
                <button onClick={() => openProduct(p.id)} className="shrink-0 overflow-hidden rounded-2xl" aria-label={`Ver ${p.name}`}>
                  <ProductImage product={p} color={p.colors?.[0]} className="h-32 w-28 sm:w-32" />
                </button>
                <div className="flex min-w-0 flex-1 flex-col py-1">
                  <p className="text-sm text-[#5B6068]">{p.category}</p>
                  <button onClick={() => openProduct(p.id)} className="truncate text-left font-display text-lg font-semibold text-[#17181C] hover:underline">{p.name}</button>
                  <p className="tabular font-semibold text-[#17181C]">{eur(p.price)}{p.compareAt && <span className="ml-2 text-sm font-normal text-[#5B6068] line-through">{eur(p.compareAt)}</span>}</p>
                  <div className="mt-auto flex flex-wrap items-center gap-2 pt-3">
                    <button disabled={p.stock === 0} onClick={() => (needsChoice ? openProduct(p.id) : quickAdd(p.id))}
                      className="flex h-10 items-center gap-2 rounded-full bg-[#2E4BF0] px-4 text-sm font-semibold text-white hover:bg-[#2340D8] disabled:bg-[#B9BBB5]">
                      <ShoppingBag size={15} />{p.stock === 0 ? 'Agotado' : needsChoice ? `Elegir ${(p.sizeLabel ?? 'talla').toLowerCase()}` : 'Añadir'}
                    </button>
                    <button onClick={() => toggleWish(p.id)} className="flex h-10 items-center gap-1.5 rounded-full px-3 text-sm text-[#5B6068] hover:text-[#C2252B]">
                      <Trash2 size={15} />Quitar
                    </button>
                  </div>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

