const money = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
const moneyRound = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 });

/** 249 → "249 €", 29.9 → "29,90 €" */
export const eur = (n: number) => (Number.isInteger(n) ? moneyRound.format(n) : money.format(n));
export const eurExact = (n: number) => money.format(n);

/** Fecha de entrega estimada saltando fines de semana. */
export function deliveryDate(businessDays: number, from = new Date()) {
  const d = new Date(from);
  let left = businessDays;
  while (left > 0) {
    d.setDate(d.getDate() + 1);
    if (d.getDay() !== 0 && d.getDay() !== 6) left--;
  }
  return d;
}

export const shortDate = (d: Date) => d.toLocaleDateString('es-ES', { weekday: 'short', day: 'numeric', month: 'short' });
export const longDate = (d: Date) => d.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' });

export function relativeDays(iso: string) {
  const days = Math.round((Date.now() - new Date(iso).getTime()) / 864e5);
  if (days <= 0) return 'hoy';
  if (days === 1) return 'ayer';
  return `hace ${days} días`;
}

export const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;

import { useEffect, useState } from 'react';
import { byId } from '../data/products';

export type CartLine = { key: string; productId: string; color?: string; size?: string; qty: number };
export type Shipping = 'estandar' | 'expres' | 'tienda';
export type Address = { email: string; name: string; phone: string; street: string; city: string; zip: string; province: string };
export type Order = {
  id: string; createdAt: string; lines: CartLine[]; address: Address; shipping: Shipping;
  payment: 'tarjeta' | 'bizum'; code?: string; totals: Totals; status: 'Confirmado' | 'Enviado' | 'Entregado';
};
export type Totals = { subtotal: number; discount: number; shipping: number; total: number; freeShipping: boolean };

const PREFIX = 'objeto-tienda:';

/** Estado persistido en localStorage (con valor inicial si es la primera vez). */
export function usePersistent<T>(key: string, initial: T) {
  const [value, setValue] = useState<T>(() => {
    try {
      const raw = localStorage.getItem(PREFIX + key);
      return raw ? (JSON.parse(raw) as T) : initial;
    } catch {
      return initial;
    }
  });
  useEffect(() => {
    try { localStorage.setItem(PREFIX + key, JSON.stringify(value)); } catch { /* sin almacenamiento */ }
  }, [key, value]);
  return [value, setValue] as const;
}

export function clearStorage() {
  try {
    Object.keys(localStorage).filter(k => k.startsWith(PREFIX)).forEach(k => localStorage.removeItem(k));
  } catch { /* nada */ }
}

export const FREE_SHIPPING_FROM = 60;
export const SHIPPING_OPTIONS: { id: Shipping; name: string; detail: string; price: number }[] = [
  { id: 'estandar', name: 'Estándar', detail: '2–4 días laborables', price: 4.9 },
  { id: 'expres', name: 'Exprés', detail: 'Mañana antes de las 14:00', price: 9.9 },
