type Coupon = { code: string; label: string; minimum?: number; apply: (subtotal: number) => number; freeShipping?: boolean };
export const COUPONS: Coupon[] = [
  { code: 'OBJETO10', label: '10 % en tu primer pedido', apply: s => s * 0.1 },
  { code: 'BIENVENIDA15', label: '15 € a partir de 100 €', minimum: 100, apply: () => 15 },
  { code: 'ENVIOGRATIS', label: 'Envío estándar gratis', apply: () => 0, freeShipping: true },
];

export function checkCoupon(code: string, subtotal: number): { ok: true; coupon: Coupon } | { ok: false; error: string } {
  const c = COUPONS.find(x => x.code === code.trim().toUpperCase());
  if (!c) return { ok: false, error: 'Ese código no existe o ha caducado.' };
  if (c.minimum && subtotal < c.minimum) return { ok: false, error: `Este código es para pedidos desde ${c.minimum} €.` };
  return { ok: true, coupon: c };
}

export const linePrice = (l: CartLine) => (byId(l.productId)?.price ?? 0) * l.qty;

export function computeTotals(lines: CartLine[], code: string | undefined, shipping: Shipping = 'estandar'): Totals {
  const subtotal = lines.reduce((s, l) => s + linePrice(l), 0);
  const res = code ? checkCoupon(code, subtotal) : null;
  const coupon = res && res.ok ? res.coupon : null;
  const discount = coupon ? Math.min(subtotal, Math.round(coupon.apply(subtotal) * 100) / 100) : 0;
  const opt = SHIPPING_OPTIONS.find(o => o.id === shipping)!;
  const freeShipping = subtotal - discount >= FREE_SHIPPING_FROM || !!coupon?.freeShipping;
  const ship = lines.length === 0 ? 0 : shipping === 'estandar' && freeShipping ? 0 : opt.price;
  return { subtotal, discount, shipping: ship, total: Math.max(0, subtotal - discount + ship), freeShipping };
}

